<?php require __DIR__.'/../includes/app.php';require_admin();$rows=db()->query("SELECT i.codigo_confirmacion,i.familia,i.responsable,i.telefono,i.estudiante,i.grado_seccion,a.nombre actividad,co.nombre comision,t.hora_inicio,t.hora_fin,i.estado,i.creado_en FROM inscripciones i JOIN actividades a ON a.id=i.actividad_id JOIN comisiones co ON co.id=i.comision_id JOIN turnos t ON t.id=i.turno_id ORDER BY a.nombre,co.nombre,t.hora_inicio,i.familia")->fetchAll();header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename=inscripciones-bueyes-morados-'.date('Ymd-His').'.csv');$o=fopen('php://output','w');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,['Código','Familia','Responsable','Teléfono','Estudiante','Grado/Sección','Actividad','Comisión','Inicio','Fin','Estado','Registro'],';');foreach($rows as $r)fputcsv($o,array_values($r),';');fclose($o);exit;
